        nQueueHead[nQueueTail - 1] = (int)sEquiv1;
        nQueueCount = nQueueTail;
        if (sEquiv2) {
          nQueueHead[nQueueTail] = (int)sEquiv2;
          nQueueCount = nQueueTail + 1;
        }
